/**
 * Kecilkan foto sampai ukurannya ≤ `maxBytes` dengan meng-encode ulang ke JPEG.
 *
 * Foto kamera HP umumnya 4–10 MB, jadi menolaknya begitu saja membuat PIC
 * tidak bisa mengirim apa pun. Di sini kualitas JPEG diturunkan bertahap, dan
 * bila belum cukup, resolusinya ikut dikecilkan. File yang sudah cukup kecil
 * dikembalikan apa adanya.
 *
 * Resolve File hasil kompres, atau null bila tetap tidak bisa di bawah batas
 * (mis. gambar tidak bisa dibaca browser).
 */
const SISI_TERPANJANG = 2560 // cukup untuk membaca tulisan pada dokumen
const KUALITAS = [0.85, 0.75, 0.65, 0.55]
const SKALA_MINIMUM = 0.25

export async function kompresFoto(file, maxBytes) {
	if (!file) return null
	if (file.size <= maxBytes) return file

	let gambar
	try {
		// `from-image` menerapkan orientasi EXIF supaya foto potret tidak miring.
		gambar = await createImageBitmap(file, { imageOrientation: 'from-image' })
	} catch (e) {
		return null
	}

	const nama = file.name.replace(/\.[^.]+$/, '') + '.jpg'
	let skala = Math.min(1, SISI_TERPANJANG / Math.max(gambar.width, gambar.height))
	try {
		while (skala >= SKALA_MINIMUM) {
			const canvas = document.createElement('canvas')
			canvas.width = Math.round(gambar.width * skala)
			canvas.height = Math.round(gambar.height * skala)
			canvas.getContext('2d').drawImage(gambar, 0, 0, canvas.width, canvas.height)
			for (const q of KUALITAS) {
				const blob = await new Promise((resolve) => canvas.toBlob(resolve, 'image/jpeg', q))
				if (blob && blob.size <= maxBytes) {
					return new File([blob], nama, { type: 'image/jpeg' })
				}
			}
			skala *= 0.75
		}
	} finally {
		gambar.close?.()
	}
	return null
}
